window.docContents[151].resolve({"/Airy-and-Related-Functions/#chapter-9":{"contents":"LMLF has bounded Olver transcriptions for an Airy integral and for real Airy basis and auxiliary\nmaterial. They remain unreconciled and do not identify an accepted Ai, Bi, or Scorer object.\n\nQualitative view.The source records support future statements about Airy normalization, real basis functions, and\nauxiliaries, but no statement is currently claimed as a proved LMLF theorem.Quantitative view.Finite asymptotic expansions, explicit error envelopes, turning-point estimates, derivatives, and\nzero bounds remain future cards. No Lean disclosure is shown because the family has no accepted\ndeclaration.\n\n\n\n","context":"LMLF · Mathematical Functions with Lean","header":"9. Airy and Related Functions","id":"/Airy-and-Related-Functions/#chapter-9"},"/Airy-and-Related-Functions/Chapter-contents/#LMLF-___-Mathematical-Functions-with-Lean--Airy-and-Related-Functions--Chapter-contents--Airy-functions":{"contents":"* 9.1 Special Notation* 9.2 Differential Equation* 9.3 Graphics* 9.4 Maclaurin Series* 9.5 Integral Representations* 9.6 Relations to Other Functions* 9.7 Asymptotic Expansions* 9.8 Modulus and Phase* 9.9 Zeros* 9.10 Integrals* 9.11 Products\n\n","context":"LMLF · Mathematical Functions with Lean\u0009Airy and Related Functions\u0009Chapter contents","header":"9.1.1. Airy functions","id":"/Airy-and-Related-Functions/Chapter-contents/#LMLF-___-Mathematical-Functions-with-Lean--Airy-and-Related-Functions--Chapter-contents--Airy-functions"}});